INSERT INTO courses(id,slug,title,short_description,description,subject_id,instructor_id,school_level,status,outcomes,prerequisites,palette,illustration,featured,published_at) VALUES('thales','thales','La géométrie, enfin à votre portée','Comprendre Thalès et Pythagore, reconnaître les bonnes situations et résoudre des problèmes avec méthode.','Comprendre Thalès et Pythagore, reconnaître les bonnes situations et résoudre des problèmes avec méthode.','maths','instructor-1','MIDDLE','PUBLISHED',ARRAY['Reconnaître des triangles semblables','Appliquer le théorème de Thalès','Résoudre un problème de géométrie']::text[],ARRAY['Savoir calculer avec des proportions','Reconnaître des droites parallèles']::text[],'blue','geometry',true,'2026-10-14T10:00:00Z') ON CONFLICT DO NOTHING;
INSERT INTO lessons(id,course_id,title,position,kind,estimated_minutes,preview_allowed,blocks) VALUES('thales-1','thales','Observer et comprendre les triangles',0,'READING',8,true,'[{"type":"PARAGRAPH","text":"Observer et comprendre les triangles. Lorsque deux triangles sont dans une configuration de Thalès, les côtés correspondants sont proportionnels. Repérez d’abord les points alignés et les droites parallèles avant d’écrire les rapports."},{"type":"EXAMPLE","title":"Un exemple pour comprendre","text":"Dans le triangle ABC, M est sur [AB] et N sur [AC], avec (MN) parallèle à (BC). Si AM = 3 cm, AB = 6 cm et AC = 8 cm, alors AM / AB = AN / AC : AN = 4 cm."}]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO lessons(id,course_id,title,position,kind,estimated_minutes,preview_allowed,blocks) VALUES('thales-2','thales','Le théorème de Thalès pas à pas',1,'READING',12,false,'[{"type":"PARAGRAPH","text":"Le théorème de Thalès pas à pas. Lorsque deux triangles sont dans une configuration de Thalès, les côtés correspondants sont proportionnels. Repérez d’abord les points alignés et les droites parallèles avant d’écrire les rapports."},{"type":"EXAMPLE","title":"Un exemple pour comprendre","text":"Dans le triangle ABC, M est sur [AB] et N sur [AC], avec (MN) parallèle à (BC). Si AM = 3 cm, AB = 6 cm et AC = 8 cm, alors AM / AB = AN / AC : AN = 4 cm."}]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO lessons(id,course_id,title,position,kind,estimated_minutes,preview_allowed,blocks) VALUES('thales-3','thales','Passer de la figure au calcul',2,'READING',15,false,'[{"type":"PARAGRAPH","text":"Passer de la figure au calcul. Lorsque deux triangles sont dans une configuration de Thalès, les côtés correspondants sont proportionnels. Repérez d’abord les points alignés et les droites parallèles avant d’écrire les rapports."},{"type":"EXAMPLE","title":"Un exemple pour comprendre","text":"Dans le triangle ABC, M est sur [AB] et N sur [AC], avec (MN) parallèle à (BC). Si AM = 3 cm, AB = 6 cm et AC = 8 cm, alors AM / AB = AN / AC : AN = 4 cm."}]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO lessons(id,course_id,title,position,kind,estimated_minutes,preview_allowed,blocks) VALUES('thales-4','thales','À vous de jouer : problèmes guidés',3,'READING',10,false,'[{"type":"PARAGRAPH","text":"À vous de jouer : problèmes guidés. Lorsque deux triangles sont dans une configuration de Thalès, les côtés correspondants sont proportionnels. Repérez d’abord les points alignés et les droites parallèles avant d’écrire les rapports."},{"type":"EXAMPLE","title":"Un exemple pour comprendre","text":"Dans le triangle ABC, M est sur [AB] et N sur [AC], avec (MN) parallèle à (BC). Si AM = 3 cm, AB = 6 cm et AC = 8 cm, alors AM / AB = AN / AC : AN = 4 cm."}]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO courses(id,slug,title,short_description,description,subject_id,instructor_id,school_level,status,outcomes,prerequisites,palette,illustration,featured,published_at) VALUES('photosynthese','photosynthese','Explorer le monde vivant','Des cellules aux écosystèmes : découvrez comment les plantes transforment la lumière en énergie.','Des cellules aux écosystèmes : découvrez comment les plantes transforment la lumière en énergie.','sciences','instructor-2','SECONDARY','PUBLISHED',ARRAY['Expliquer la photosynthèse','Identifier les besoins d’une plante','Relier les plantes à leur écosystème']::text[],ARRAY['Identifier les principales parties d’une plante']::text[],'green','plant',false,'2026-10-14T10:00:00Z') ON CONFLICT DO NOTHING;
INSERT INTO lessons(id,course_id,title,position,kind,estimated_minutes,preview_allowed,blocks) VALUES('photosynthese-1','photosynthese','Une plante, comment ça fonctionne ?',0,'READING',8,true,'[{"type":"PARAGRAPH","text":"Une plante, comment ça fonctionne ?. Les plantes chlorophylliennes utilisent l’énergie lumineuse pour produire de la matière organique à partir d’eau et de dioxyde de carbone. Cette photosynthèse libère du dioxygène."},{"type":"EXAMPLE","title":"Un exemple pour comprendre","text":"Une feuille éclairée reçoit de l’eau par les racines et du dioxyde de carbone par les échanges avec l’air. La lumière apporte l’énergie nécessaire à la fabrication de matière organique."}]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO lessons(id,course_id,title,position,kind,estimated_minutes,preview_allowed,blocks) VALUES('photosynthese-2','photosynthese','Le rôle de la lumière',1,'READING',12,false,'[{"type":"PARAGRAPH","text":"Le rôle de la lumière. Les plantes chlorophylliennes utilisent l’énergie lumineuse pour produire de la matière organique à partir d’eau et de dioxyde de carbone. Cette photosynthèse libère du dioxygène."},{"type":"EXAMPLE","title":"Un exemple pour comprendre","text":"Une feuille éclairée reçoit de l’eau par les racines et du dioxyde de carbone par les échanges avec l’air. La lumière apporte l’énergie nécessaire à la fabrication de matière organique."}]'::jsonb) ON CONFLICT DO NOTHING;
