INSERT INTO lessons(id,course_id,title,position,kind,estimated_minutes,preview_allowed,blocks) VALUES('expression-1','expression','Une idée, un paragraphe',0,'READING',8,true,'[{"type":"PARAGRAPH","text":"Une idée, un paragraphe. Un paragraphe argumentatif développe une idée principale. Une explication et un exemple rendent cette idée plus claire. Les connecteurs aident le lecteur à suivre le raisonnement."},{"type":"EXAMPLE","title":"Un exemple pour comprendre","text":"« Lire régulièrement enrichit le vocabulaire. En effet, les histoires nous exposent à des mots variés. Par exemple, un récit de voyage permet de découvrir le vocabulaire des paysages. »"}]'::jsonb) ON CONFLICT DO NOTHING;
