INSERT INTO lessons(id,course_id,title,position,kind,estimated_minutes,preview_allowed,blocks) VALUES('code-1','code','Penser comme un programmeur',0,'READING',8,true,'[{"type":"PARAGRAPH","text":"Penser comme un programmeur. Un algorithme est une suite d’instructions pour résoudre un problème. Une condition choisit une action selon une situation. Une boucle répète une action."},{"type":"EXAMPLE","title":"Un exemple pour comprendre","text":"Pour arroser trois plantes : répéter trois fois « prendre une plante et l’arroser ». Si la terre est déjà humide, ne pas ajouter d’eau. La boucle organise la répétition ; la condition adapte l’action."}]'::jsonb) ON CONFLICT DO NOTHING;
