INSERT INTO lessons(id,course_id,title,position,kind,estimated_minutes,preview_allowed,blocks) VALUES('fractions-1','fractions','Partager en parts égales',0,'READING',8,true,'[{"type":"PARAGRAPH","text":"Partager en parts égales. Une fraction représente une ou plusieurs parts d’un tout partagé en parts égales. Le dénominateur indique le nombre de parts du tout ; le numérateur indique les parts prises."},{"type":"EXAMPLE","title":"Un exemple pour comprendre","text":"Un gâteau est partagé en quatre parts égales. Si vous en prenez une, vous avez 1/4 du gâteau. Deux parts représentent 2/4, soit la moitié."}]'::jsonb) ON CONFLICT DO NOTHING;
